contract InvMutTest is Test {
    C c;
    Signer maker;
    DummyToken base;

    function setUp() public {
        c = new C("", 0, address(this));
        maker = new Signer();
        base = new DummyToken();
    }

    function testFuzz_property(uint256 strike, uint256 duration, address to) public {
        vm.assume(to != address(0) && to != address(maker));
        duration = bound(duration, 1 days, 9_999 days);
        strike = bound(strike, 0, type(uint128).max);

        vm.warp(1_000);

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(base),
            strike: strike,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + 100,
            nonce: 0,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        uint256[] memory noIds = new uint256[](0);

        vm.prank(address(maker));
        c.fillOrder(order, "", noIds);

        uint256 makerPositionId = uint256(c.hashOrder(order));

        vm.prank(address(maker));
        c.transferFrom(address(maker), to, makerPositionId);

        assertTrue(c.ownerOf(makerPositionId) == to);
    }
