pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // baseAsset with code that accepts ERC20 transferFrom calls (empty success return)
    fallback() external {
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }

    function setUp() public {
        c = new C("", 0, address(this));
    }

    function testFuzz_property(uint256 nonce, address recipient) public {
        vm.assume(recipient != address(0));
        vm.warp(1000);

        Signer signer = new Signer();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(signer),
            isCall: true,
            isLong: true,
            baseAsset: address(this),
            strike: 0,
            premium: 0,
            duration: 1,
            expiration: 2000,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig;
        c.fillOrder(order, sig, new uint256[](0));

        uint256 id = uint256(c.hashOrder(order));

        // authorized caller (the token owner itself) transfers to the requested recipient
        vm.prank(address(signer));
        c.transferFrom(address(signer), recipient, id);

        assertTrue(c.ownerOf(id) == recipient);
    }
}

// adversarial counterparty: contract-based order maker that yields a valid ERC1271 signature
contract Signer {
    function isValidSignature(bytes32, bytes calldata) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }

    // accept stray ERC20-style calls with empty (success) return data
    fallback() external {}
}

