pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(uint256 makerKey, uint256 duration, address recipient) public {
        vm.assume(makerKey > 0 && makerKey < 2**252);
        vm.assume(recipient != address(0) && recipient != address(this));
        duration = bound(duration, 1, 10_000 days - 1);

        address maker = vm.addr(makerKey);

        C.Order memory order;
        order.maker = maker;
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(this);
        order.strike = 0;
        order.premium = 0;
        order.duration = duration;
        order.expiration = block.timestamp + 1000 days;
        order.nonce = 0;

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(makerKey, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;
        order.erc20Assets = erc20Assets;
        order.erc721Assets = erc721Assets;

        vm.prank(maker);
        uint256 longPositionId = c.fillOrder(order, signature, new uint256[](0));
        assertEq(longPositionId, uint256(orderHash));

        // General rule: a minted position is owned by the filler and the owner can transferFrom it.
        vm.prank(maker);
        bool ok;
        try c.transferFrom(maker, recipient, longPositionId) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "minted position must be owned and transferable");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address fakeToken;

    function setUp() public {
        fakeToken = address(new FakeToken());
        c = new C("", 0, address(this));
    }

    // ERC-1271 wallet so the fuzzer-created orders verify without vm.sign
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }

    function testFuzz_property(
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiryOffset,
        uint256 nonce
    ) public {
        strike = bound(strike, 1, 1e30);
        premium = bound(premium, 0, 1e30);
        duration = bound(duration, 1, 9_999 days);
        expiryOffset = bound(expiryOffset, 1, 1_000 days);
        nonce = bound(nonce, 0, 1e18);

        address[] memory emptyAddrs = new address[](0);
        C.ERC20Asset[] memory noErc20 = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory noErc721 = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: false,
            isLong: false,
            baseAsset: fakeToken,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + expiryOffset,
            nonce: nonce,
            whitelist: emptyAddrs,
            floorTokens: emptyAddrs,
            erc20Assets: noErc20,
            erc721Assets: noErc721
        });

        bytes memory emptySig = new bytes(0);
        uint256[] memory noFloorIds = new uint256[](0);

        vm.prank(address(0xb0b));
        uint256 positionId = c.fillOrder(order, emptySig, noFloorIds);

        // General rule: a position NFT minted by a successful fillOrder is owned,
        // so its tokenURI is queryable and equals baseURI ++ id.
        bool ok;
        string memory uri;
        try c.tokenURI(positionId) returns (string memory u) {
            ok = true;
            uri = u;
        } catch {
            ok = false;
        }

        assertTrue(ok && keccak256(bytes(uri)) == keccak256(bytes(string.concat("", _idStr(positionId)))));
    }

    function _idStr(uint256 v) internal pure returns (string memory) {
        if (v == 0) return "0";
        uint256 digits;
        uint256 t = v;
        while (t != 0) { digits++; t /= 10; }
        bytes memory b = new bytes(digits);
        while (v != 0) { digits--; b[digits] = bytes1(uint8(48 + v % 10)); v /= 10; }
        return string(b);
    }
}

contract FakeToken {
