    fallback() external {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(uint256 strike, uint256 duration, address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(this));

        // Adversarial environment: the order maker is an ERC1271 signer helper so any
        // signature passes SignatureChecker, and a stub ERC20 base asset whose
        // transferFrom always succeeds.
        ERC1271Maker maker = new ERC1271Maker();
        FakeERC20 base = new FakeERC20();

        C.Order memory order;
        order.maker = address(maker);
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(base);
        order.strike = bound(strike, 0, 1e18);
        order.premium = 0;
        order.duration = bound(duration, 1, 100 days);
        order.expiration = block.timestamp + 1000 days;
        order.nonce = 0;

        bytes memory sig = new bytes(65);
        uint256[] memory floorIds = new uint256[](0);

        // Filling the order mints the short position (orderHash) to the maker and
        // the long position to the caller (this test contract).
        uint256 positionId = c.fillOrder(order, sig, floorIds);
        uint256 makerTokenId = uint256(c.hashOrder(order));

        // Drive c through transferFrom as an authorized owner.
        vm.prank(address(maker));
        c.transferFrom(address(maker), recipient, makerTokenId);

        c.transferFrom(address(this), recipient, positionId);

        // General rule: after a successful transfer, the recorded owner of the token
        // is exactly `to`, and ownership data is consistent for every transferred id.
        assertTrue(c.ownerOf(makerTokenId) == recipient && c.ownerOf(positionId) == recipient);
    }
}

contract ERC1271Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract FakeERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}
